source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate the full-width/full-height color-2 divider.
    divider = None
    axis = None
    for r, row in enumerate(grid):
        if all(v == 2 for v in row):
            divider, axis = r, 0
            break
    if divider is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                divider, axis = c, 1
                break
    if divider is None:
        return [row[:] for row in grid]

    # Background is the most common color other than the divider.
    counts = {}
    for row in grid:
        for v in row:
            if v != 2:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # The non-background object lies on one side of the divider.
    if axis == 0:
        coords = [(r, c) for r in range(h) for c in range(w)
                  if r != divider and grid[r][c] != 2 and grid[r][c] != bg]
        if not coords:
            return [row[:] for row in grid]
        rs = [p[0] for p in coords]
        below = min(rs) > divider
        shift = (divider + 1 - min(rs)) if below else (divider - 1 - max(rs))
        out = [row[:] for row in grid]
        for r, c in coords:
            out[r][c] = bg
        for r, c in coords:
            out[r + shift][c] = grid[r][c]
        far = max(r for r, c in coords) + shift + 1 if below else min(r for r, c in coords) + shift - 1
        if 0 <= far < h:
            out[far] = [8] * w
        return out
    else:
        coords = [(r, c) for r in range(h) for c in range(w)
                  if c != divider and grid[r][c] != 2 and grid[r][c] != bg]
        if not coords:
            return [row[:] for row in grid]
        cs = [p[1] for p in coords]
        right = min(cs) > divider
        shift = (divider + 1 - min(cs)) if right else (divider - 1 - max(cs))
        out = [row[:] for row in grid]
        for r, c in coords:
            out[r][c] = bg
        for r, c in coords:
            out[r][c + shift] = grid[r][c]
        far = max(c for r, c in coords) + shift + 1 if right else min(c for r, c in coords) + shift - 1
        if 0 <= far < w:
            for r in range(h):
                out[r][far] = 8
        return out
'''
